before.content:
:8080 {
  encode zstd gzip
  @relay path /api/* /metrics
  reverse_proxy @relay relay:18090

after.content:
:8080 {
  log {
    format filter {
      wrap json
      fields {
        request>headers>X-Ji-Terminal-Bootstrap delete
        request>headers>Authorization delete
        request>headers>Cookie delete
      }
    }
  }
  encode zstd gzip
  @relay path /api/* /metrics
  reverse_proxy @relay relay:18090
